import math
r=lambda d:math.radians(d)
res=math.tan(r(55))/(1/math.tan(r(35)))
opts={'A':1,'B':1/math.cos(r(55)),'C':0,'D':math.cos(r(35))}
for k,v in opts.items():
    assert (abs(res-v)<1e-9)==(k=='A')

import math
A=0.7
lhs=math.sin(A)/(1+math.cos(A))+1/math.tan(A)
opts={'A':math.sin(A)+math.cos(A),'B':math.cos(A),'C':math.sin(A),'D':1/math.sin(A)}
for k,v in opts.items():
    assert (abs(lhs-v)<1e-9)==(k=='D')

from sympy import symbols,simplify,Rational
a=symbols('a',positive=True)
opts={'A':1/(100*a**2),'B':1/(25*a**4),'C':1/(25*a**2),'D':1/(100*a**4)}
for k,v in opts.items():
    assert (simplify(4*a**2*v-(1/(5*a))**2)==0)==(k=='D')

def c(w): return sum(27-(ord(x)-64) for x in w)*len(w)
assert c('HIT')==132 and c('SBYZ')==144
r=c('YRF')
o={'A':108,'B':124,'C':112,'D':96}
assert r==o['D']
for k in 'ABC': assert r!=o[k]

